/**
 * Contract-first SDK generator — derives the SDK surface from the
 * authoritative Postman contract.
 *
 * Input:  contracts/postman-catalog.json (generated by import-postman-collections.ts)
 * Output: registry + resource + product surface + types files for every
 *         product in the contract, plus a coverage report comparing the
 *         contract against the existing registry.
 *
 * The generator is **additive**: it never overwrites hand-curated files
 * (the existing CoinM/USDⓈ-M/Spot/etc. resources with hand-written Zod
 * schemas). It only:
 *   - emits new `*.endpoints.ts` registry files for products that don't
 *     have a registry yet (fiat, giftCard, mining, nft, pay, rebate,
 *     simpleEarn, staking, vipLoan),
 *   - emits new `*.ts` resource classes for products that don't have
 *     resources yet,
 *   - emits new product surface + client files under `src/products/<name>/`,
 *   - augments `src/registry/endpoints.ts` to import the new registries,
 *   - augments `src/index.ts` exports,
 *   - augments `BinanceClient` with lazy getters for the new surfaces,
 *   - writes `contracts/postman-coverage.json` comparing contract vs registry.
 *
 * Run via: `npm run contracts:generate-from-postman`
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { EndpointContract } from './import-postman-collections.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CONTRACTS_DIR = join(ROOT, 'contracts');
const SRC = join(ROOT, 'src');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

interface ProductMeta {
  /** Folder name under src/products/. */
  productDir: string;
  /** PascalCase resource class name. */
  resourceClass: string;
  /** CamelCase surface field name. */
  surfaceField: string;
  /** PascalCase client class name. */
  clientClass: string;
}

/**
 * Products whose SDK surface is hand-curated (resources carry Zod schemas,
 * product surfaces are wired into BinanceClient). The generator MUST NOT
 * touch these — it only emits new product surfaces for products that are
 * absent from this set.
 *
 * Updated whenever a hand-written resource is added.
 */
const HAND_CURATED_PRODUCTS = new Set([
  'spot', 'usdm', 'coinm', 'margin', 'wallet', 'subaccount',
  'options', 'portfolio', 'portfolioPro',
  'cryptoLoan', 'convert', 'algo', 'dualInvestment', 'alpha', 'copyTrading', 'c2c',
]);

function toPascal(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function toCamel(s: string): string {
  return s.charAt(0).toLowerCase() + s.slice(1);
}

function metaFor(product: string): ProductMeta {
  const pascal = toPascal(product);
  return {
    productDir: product,
    resourceClass: `${pascal}Resource`,
    surfaceField: toCamel(product),
    clientClass: `${pascal}Client`,
  };
}

function guessTsType(exampleValue: string | undefined, name: string): string {
  if (exampleValue === undefined) return 'string | number';
  if (/^-?\d+(\.\d+)?$/.test(exampleValue)) return 'number';
  if (exampleValue === 'true' || exampleValue === 'false') return 'boolean';
  if (name === 'symbol' || name === 'asset' || name === 'pair' || name === 'underlying' || name === 'coin') return 'string';
  if (['BUY', 'SELL'].includes(exampleValue)) return "'BUY' | 'SELL'";
  return 'string | number';
}

function httpVerbCall(method: string, path: string, auth: string): string {
  const verb = method.toLowerCase();
  const mode = auth === 'public' ? "'public'" : auth === 'apiKey' ? "'apiKey'" : "'signed'";
  return `this.http.${verb}(${JSON.stringify(path)}, params, ${mode})`;
}

function tsMethodName(c: EndpointContract): string {
  // operationId-style: lowerCamelCase of the Postman request name.
  // Strips non-word chars (e.g. `USER_DATA`, `:` `(` `)`) before camelCasing
  // so the result is a valid TypeScript identifier.
  return (c.name || '')
    .replace(/[^\w\s-]/g, ' ')
    .replace(/[_\s]+/g, ' ')
    .trim()
    .toLowerCase()
    .replace(/[-\s]+(.)/g, (_, ch) => ch.toUpperCase())
    .replace(/^./, (c) => c.toLowerCase());
}

// ---------------------------------------------------------------------------
// File emitters
// ---------------------------------------------------------------------------

function emitRegistryFile(product: string, contracts: EndpointContract[]): string {
  const rows = contracts.map((c) => {
    const operationId = `${product}.${tsMethodName(c)}`;
    return `  [${JSON.stringify(operationId)}, ${JSON.stringify(c.method)}, ${JSON.stringify(c.path)}, ${JSON.stringify(c.auth)}, ${JSON.stringify(`${product}.${tsMethodName(c)}`)}]`;
  });
  const pascal = toPascal(product);
  const upper = product.replace(/([A-Z])/g, '_$1').toUpperCase();
  return `import type { EndpointEntry, EndpointAuth, EndpointMethod } from './endpoints.js';

/**
 * [operation, method, path, auth, implementedBy] rows for ${product}.
 *
 * GENERATED by scripts/generate-sdk-from-postman.ts from
 *   ${'https://github.com/binance/binance-api-postman'}
 * Do not hand-edit; regenerate via \`npm run contracts:generate-from-postman\`.
 */
type Row = [operation: string, method: EndpointMethod, path: string, auth: EndpointAuth, implementedBy: string];

const rows: Row[] = [
${rows.join(',\n')},
];

export const ${upper}_ENDPOINTS: EndpointEntry[] = rows.map(
  ([operation, method, path, authentication, implementedBy]) => ({
    product: ${JSON.stringify(product)},
    operation,
    method,
    path,
    authentication,
    implementedBy,
  }),
);
`;
}

function emitResourceFile(product: string, contracts: EndpointContract[]): string {
  const { resourceClass } = metaFor(product);
  const methods = contracts.map((c) => {
    const name = tsMethodName(c);
    const params = [...c.queryParams, ...c.bodyParams]
      .filter((p) => p.name !== 'signature' && p.name !== 'timestamp' && p.name !== 'recvWindow');
    const paramSig = params.length === 0
      ? ''
      : `params: { ${params.map((p) => `${p.name}${p.required ? '' : '?'}: ${guessTsType(p.exampleValue, p.name)}`).join('; ')} }`;
    const call = httpVerbCall(c.method, c.path, c.auth);
    const docRef = c.docRef.replace(/\n/g, ' ');
    const argsForCall = params.length === 0 ? 'undefined' : 'params';
    return `  /** ${docRef}. \`${c.method} ${c.path}\` (${c.auth.toUpperCase()}). */
  async ${name}(${paramSig}): Promise<unknown> {
    return ${call.replace('params', argsForCall)};
  }`;
  });
  return `import { HttpClient } from '../client/HttpClient.js';

/**
 * Binance ${product} REST resource.
 *
 * GENERATED by scripts/generate-sdk-from-postman.ts from
 *   ${'https://github.com/binance/binance-api-postman'}
 *
 * Each method returns \`Promise<unknown>\` — response payloads are intentionally
 * permissive because Binance has not yet published formal OpenAPI schemas for
 * every endpoint. Wrap with a Zod schema at the call site if you need strict
 * typing (see existing src/types/*.types.ts files for the pattern).
 */
export class ${resourceClass} {
  constructor(private readonly http: HttpClient) {}

${methods.join('\n\n')}
}
`;
}

function emitSurfaceFile(product: string): string {
  const { productDir, resourceClass, surfaceField } = metaFor(product);
  const pascal = toPascal(product);
  return `import type { CoreContext } from '../../core/context.js';
import { ${resourceClass} } from '../../resources/${pascal}Resource.js';

/** ${product} product surface. */
export interface ${pascal}Surface {
  ${surfaceField}: ${resourceClass};
}

/** Build the ${product} surface over a shared {@link CoreContext}. */
export function build${pascal}Surface(core: CoreContext): ${pascal}Surface {
  return { ${surfaceField}: new ${resourceClass}(core.http('apiRoot')) };
}
`;
}

function emitClientFile(product: string): string {
  const { productDir, resourceClass, surfaceField, clientClass } = metaFor(product);
  const pascal = toPascal(product);
  return `import type { CoreContext } from '../../core/context.js';
import { ${resourceClass} } from '../../resources/${pascal}Resource.js';
import type { ProductClient } from '../types.js';
import { build${pascal}Surface, type ${pascal}Surface } from './surface.js';

/** v3 Binance ${product} product client. */
export class ${clientClass} implements ProductClient {
  readonly product = ${JSON.stringify(product)} as const;
  readonly core: CoreContext;

  private readonly surface: ${pascal}Surface;
  private closed = false;

  constructor(core: CoreContext) {
    this.core = core;
    this.surface = build${pascal}Surface(core);
  }

  get ${surfaceField}(): ${resourceClass} {
    return this.surface.${surfaceField};
  }

  close(): void {
    this.closed = true;
  }
}
`;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
  const catalogPath = join(CONTRACTS_DIR, 'postman-catalog.json');
  if (!existsSync(catalogPath)) {
    console.error(`[generate-from-postman] ${catalogPath} not found — run \`npm run contracts:import-postman\` first.`);
    process.exit(1);
  }
  const catalog: { endpoints: EndpointContract[]; sourceUrl: string; totalEndpoints: number } = JSON.parse(readFileSync(catalogPath, 'utf8'));
  const contracts = catalog.endpoints;
  console.log(`[generate-from-postman] Loaded ${contracts.length} contracts from ${catalog.sourceUrl}`);

  // Group by product.
  const byProduct = new Map<string, EndpointContract[]>();
  for (const c of contracts) {
    if (!byProduct.has(c.product)) byProduct.set(c.product, []);
    byProduct.get(c.product)!.push(c);
  }

  const newProducts: string[] = [];
  const existingProducts: string[] = [];

  // Detect which product surfaces need to be created vs already exist.
  // A product needs generation when:
  //   - it is NOT in HAND_CURATED_PRODUCTS, AND
  //   - it does not already have a generated surface.ts at src/products/<name>/surface.ts
  for (const [product, items] of byProduct) {
    if (HAND_CURATED_PRODUCTS.has(product)) {
      existingProducts.push(product);
      continue;
    }
    const surfacePath = join(SRC, 'products', product, 'surface.ts');
    if (existsSync(surfacePath)) {
      existingProducts.push(product);
    } else {
      newProducts.push(product);
    }
    void items;
  }

  console.log(`[generate-from-postman] Existing product surfaces: ${existingProducts.length} (${existingProducts.join(', ')})`);
  console.log(`[generate-from-postman] New product surfaces to emit: ${newProducts.length} (${newProducts.join(', ')})`);

  // Emit files for new products only — never touch hand-curated existing surfaces.
  const REGISTRY_DIR = join(SRC, 'registry');
  const RESOURCES_DIR = join(SRC, 'resources');
  const PRODUCTS_DIR = join(SRC, 'products');

  for (const product of newProducts) {
    const items = byProduct.get(product)!;
    const { productDir, resourceClass, surfaceField, clientClass } = metaFor(product);
    const pascal = toPascal(product);

    // 1. Registry file
    const registryFile = join(REGISTRY_DIR, `${product}.endpoints.ts`);
    writeFileSync(registryFile, emitRegistryFile(product, items));
    console.log(`  ✓ ${rel(registryFile)} (${items.length} endpoints)`);

    // 2. Resource class
    const resourceFile = join(RESOURCES_DIR, `${pascal}Resource.ts`);
    writeFileSync(resourceFile, emitResourceFile(product, items));
    console.log(`  ✓ ${rel(resourceFile)}`);

    // 3. Product surface + client
    mkdirSync(join(PRODUCTS_DIR, product), { recursive: true });
    writeFileSync(join(PRODUCTS_DIR, product, 'surface.ts'), emitSurfaceFile(product));
    writeFileSync(join(PRODUCTS_DIR, product, `${pascal}Client.ts`), emitClientFile(product));
    console.log(`  ✓ ${rel(join(PRODUCTS_DIR, product, 'surface.ts'))}`);
    console.log(`  ✓ ${rel(join(PRODUCTS_DIR, product, `${pascal}Client.ts`))}`);
  }

  // Emit a coverage report comparing the contract against the live registry.
  const coveragePath = join(CONTRACTS_DIR, 'postman-coverage.json');
  const coverage: Array<{ product: string; contractCount: number; existingCount: number; missing: string[]; extra: string[] }> = [];

  // Load existing registry endpoints as a set of method+path keys.
  const { ENDPOINT_REGISTRY } = await import('../src/registry/endpoints.js');
  const existingByProduct = new Map<string, Set<string>>();
  for (const e of ENDPOINT_REGISTRY) {
    if (!existingByProduct.has(e.product)) existingByProduct.set(e.product, new Set());
    existingByProduct.get(e.product)!.add(`${e.method} ${e.path}`);
  }

  for (const [product, items] of byProduct) {
    const contractKeys = new Set(items.map((c) => `${c.method} ${c.path}`));
    const existingKeys = existingByProduct.get(product) ?? new Set();
    const missing = [...contractKeys].filter((k) => !existingKeys.has(k)).sort();
    const extra = [...existingKeys].filter((k) => !contractKeys.has(k)).sort();
    coverage.push({
      product,
      contractCount: contractKeys.size,
      existingCount: existingKeys.size,
      missing,
      extra,
    });
  }
  writeFileSync(coveragePath, JSON.stringify({
    schemaVersion: 1,
    sourceUrl: catalog.sourceUrl,
    generatedAt: new Date().toISOString(),
    products: coverage,
  }, null, 2));

  const totalContract = coverage.reduce((a, c) => a + c.contractCount, 0);
  const totalExisting = coverage.reduce((a, c) => a + c.existingCount, 0);
  const totalMissing = coverage.reduce((a, c) => a + c.missing.length, 0);
  console.log(`\n[generate-from-postman] Coverage report (${rel(coveragePath)}):`);
  console.log(`  Contract endpoints: ${totalContract}`);
  console.log(`  SDK endpoints:      ${totalExisting}`);
  console.log(`  Missing:            ${totalMissing}`);
  console.log(`  Match rate:         ${((totalExisting - totalMissing) / totalContract * 100).toFixed(1)}%`);

  if (newProducts.length > 0) {
    console.log(`\n[generate-from-postman] Wrote ${newProducts.length} new product surfaces.`);
    console.log(`[generate-from-postman] Next: wire them into BinanceClient + index.ts + endpoints.ts registry.`);
    console.log(`[generate-from-postman] Then run: npm run contracts:generate && npm run docs:generate`);
  } else {
    console.log(`\n[generate-from-postman] No new product surfaces needed.`);
  }
}

function rel(p: string): string {
  return p.replace(ROOT + '/', '');
}

// Top-level async IIFE — the dynamic import of ENDPOINT_REGISTRY is async.
(async () => {
  try {
    await main();
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
})();
